				indices := recordIndicesOfCase(trace, "w-init-term-end-event")
				trace.Records[indices[0]].New[0].Fields["c0"] = map[string]any{
					"kind": "row", "fields": map[string]any{"theString": "A", "intPrimitive": 0},
				}
