func assertResultSetQueryTypeRowForAllHavingSumJoinTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != resultSetQueryTypeRowForAllHavingSumJoinID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 3 {
		t.Fatalf("trace records = %d, want 3", len(trace.Records))
	}
	wantTimes := []string{"1970-01-01T00:00:05Z", "1970-01-01T00:00:08Z", "1970-01-01T00:00:10Z"}
	for i, record := range trace.Records {
		if record.Case != resultSetQueryTypeRowForAllHavingSumJoinCase || record.Operation != "listener" || record.Statement != "s0" || record.Sequence != uint64(i+1) || record.Time != wantTimes[i] {
			t.Fatalf("record %d metadata = %#v", i, record)
		}
		switch i {
		case 0:
			if len(record.New) != 1 || len(record.Old) != 0 {
				t.Fatalf("record %d new/old shape = %d/%d", i, len(record.New), len(record.Old))
			}
			assertResultSetQueryTypeRowForAllHavingSumJoinRow(t, record.New[0], 25)
		case 1:
			if len(record.New) != 1 || len(record.Old) != 1 {
				t.Fatalf("record %d new/old shape = %d/%d", i, len(record.New), len(record.Old))
			}
			assertResultSetQueryTypeRowForAllHavingSumJoinRow(t, record.New[0], 20)
			assertResultSetQueryTypeRowForAllHavingSumJoinRow(t, record.Old[0], 25)
		case 2:
			if len(record.New) != 0 || len(record.Old) != 1 {
				t.Fatalf("record %d new/old shape = %d/%d", i, len(record.New), len(record.Old))
			}
			assertResultSetQueryTypeRowForAllHavingSumJoinRow(t, record.Old[0], 20)
		}
	}
}

func assertResultSetQueryTypeRowForAllHavingSumJoinRow(t *testing.T, row compat.ResultRecord, want int64) {
	t.Helper()
	if row.Kind != "row" || len(row.Fields) != 1 {
		t.Fatalf("row shape = %#v", row)
	}
	value, ok := row.Fields["mySum"]
	if !ok {
		t.Fatalf("row fields = %#v", row.Fields)
	}
	number, ok := value.(json.Number)
	if !ok {
		t.Fatalf("mySum type = %T, value = %#v", value, value)
	}
	got, err := number.Int64()
	if err != nil || got != want {
		t.Fatalf("mySum = %v (err=%v), want %d", number, err, want)
	}
}

