func TestRunOutputAfterEventsCheckedInEvidenceMatchesTraceAndReplay(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	javaTrace, err := loadTraceFile(filepath.Join(root, outputAfterEventsID+".trace.json"))
	if err != nil {
		t.Fatal(err)
	}
	goTrace, err := loadTraceFile(filepath.Join(root, outputAfterEventsID+".go.trace.json"))
	if err != nil {
		t.Fatal(err)
	}
	evidence, err := loadDifferentialEvidenceFile(filepath.Join(root, outputAfterEventsID+".evidence.json"))
	if err != nil {
		t.Fatal(err)
	}
	if evidence.Status != "passing" || len(evidence.Differences) != 0 {
		t.Fatalf("checked-in evidence = %#v", evidence)
	}
	if differences := compat.DiffTraces(javaTrace, evidence.JavaTrace); len(differences) != 0 {
		t.Fatalf("checked-in evidence Java trace differs from checked-in trace: %#v", differences)
	}
	if differences := compat.DiffTraces(goTrace, evidence.GoTrace); len(differences) != 0 {
		t.Fatalf("checked-in evidence Go trace differs from evidence Go trace: %#v", differences)
	}
	if evidence.JavaCommit != outputAfterEventsJavaCommit ||
		!reflect.DeepEqual(evidence.JavaRuntimeIDs, outputAfterEventsJavaRuntimeIDs) ||
		!reflect.DeepEqual(evidence.JavaSourceFiles, []string{outputAfterEventsSource}) ||
		!reflect.DeepEqual(evidence.JavaExecutions, outputAfterEventsJavaExecutions) {
		t.Fatalf("checked-in Java metadata = %#v", evidence)
	}
	assertOutputAfterEventsTrace(t, javaTrace)
	assertOutputAfterEventsTrace(t, goTrace)

	scenarioPath := filepath.Join(root, outputAfterEventsID+".json")
	scenarioData, err := os.ReadFile(scenarioPath)
	if err != nil {
		t.Fatal(err)
	}
	var rawScenario struct {
		Version string        `json:"version"`
		ID      string        `json:"id"`
		Steps   []compat.Step `json:"steps"`
	}
	if err := json.Unmarshal(scenarioData, &rawScenario); err != nil {
		t.Fatal(err)
	}
	scenario := compat.Scenario{Version: rawScenario.Version, ID: rawScenario.ID, Steps: rawScenario.Steps}
	scenarioJSON, err := json.Marshal(scenario)
	if err != nil {
		t.Fatal(err)
	}
	evidenceScenarioJSON, err := json.Marshal(evidence.Scenario)
	if err != nil {
		t.Fatal(err)
	}
	var scenarioValue, evidenceScenarioValue any
	if err := json.Unmarshal(scenarioJSON, &scenarioValue); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(evidenceScenarioJSON, &evidenceScenarioValue); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(scenarioValue, evidenceScenarioValue) {
		t.Fatal("checked-in evidence scenario differs from checked-in scenario")
	}

	canonicalEvidence, err := compat.NewDifferentialEvidence(
		outputAfterEventsJavaCommit,
		outputAfterEventsJavaRuntimeIDs,
		[]string{outputAfterEventsSource},
		outputAfterEventsJavaExecutions,
		scenario, javaTrace, evidence.GoTrace)
	if err != nil {
		t.Fatal(err)
	}
	if canonicalEvidence.Status != "passing" || len(canonicalEvidence.Differences) != 0 {
		t.Fatalf("checked-in Java trace is not a passing comparison: %#v", canonicalEvidence.Differences)
	}

	var stdout, stderr bytes.Buffer
	if code := Run([]string{
		"-mode", outputAfterEventsID,
		"-scenario", scenarioPath,
	}, &stdout, &stderr); code != 0 {
		t.Fatalf("replay exit code = %d, stderr = %q", code, stderr.String())
	}
	replayed, err := compat.LoadTrace(strings.NewReader(stdout.String()))
	if err != nil {
		t.Fatal(err)
	}
	if differences := compat.DiffTraces(evidence.GoTrace, replayed); len(differences) != 0 {
		t.Fatalf("checked-in evidence Go trace differs from current replay: %#v", differences)
	}
	assertOutputAfterEventsTrace(t, replayed)
}

func TestRunOutputAfterEventsRejectsMalformedRawScenario(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	data, err := os.ReadFile(filepath.Join(root, outputAfterEventsID+".json"))
	if err != nil {
		t.Fatal(err)
	}
	tests := []struct {
		name   string
		mutate func([]byte) []byte
	}{
		{name: "top-level-extra", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"steps": [`), []byte(`"extra": 0, "steps": [`), 1)
		}},
		{name: "case-extra", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"case": "after-3-events",`), []byte(`"case": "after-3-events", "extra": 0,`), 1)
		}},
		{name: "case-runtime-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"runtimeId": "java-runtime-34bfe3c4c56f505d50cd"`), []byte(`"runtimeId": "java-runtime-wrong"`), 1)
		}},
		{name: "payload-extra", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"theString": "E1", "intPrimitive": 0`), []byte(`"theString": "E1", "intPrimitive": 0, "extra": 0`), 1)
		}},
		{name: "wrong-event", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"eventType": "SupportBean"`), []byte(`"eventType": "WrongEvent"`), 1)
		}},
		{name: "set-variable-name-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"name": "myvar0"`), []byte(`"name": "myvar9"`), 1)
		}},
		{name: "read-variable-name-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"name": "myvar1"`), []byte(`"name": "myvar9"`), 1)
		}},
		{name: "advance-time-missing-at", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`{"op": "advance-time", "at": "1970-01-01T00:00:20Z"}`), []byte(`{"op": "advance-time"}`), 1)
		}},
		{name: "advance-time-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`{"op": "advance-time", "at": "1970-01-01T00:00:20Z"}`), []byte(`{"op": "advance-time", "at": "1970-01-01T00:00:19Z"}`), 1)
		}},
		{name: "trailing-json", mutate: func(data []byte) []byte {
			return append(append([]byte(nil), data...), []byte("\n{}\n")...)
		}},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			mutated := test.mutate(data)
			if bytes.Equal(mutated, data) {
				t.Fatalf("raw mutation %q did not change scenario", test.name)
			}
			scenarioPath := filepath.Join(t.TempDir(), "scenario.json")
			if err := os.WriteFile(scenarioPath, mutated, 0o644); err != nil {
				t.Fatal(err)
			}
			var stdout, stderr bytes.Buffer
			if code := Run([]string{
				"-mode", outputAfterEventsID,
				"-scenario", scenarioPath,
			}, &stdout, &stderr); code == 0 {
				t.Fatalf("malformed scenario %q unexpectedly replayed: stdout=%q stderr=%q", test.name, stdout.String(), stderr.String())
			}
		})
	}
}

func TestRunOutputAfterEventsRuntimeIDMappingMatchesScenario(t *testing.T) {
	path := filepath.Join("..", "..", "..", "testdata", "parity", outputAfterEventsID+".json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var document struct {
		Version       string   `json:"version"`
		ID            string   `json:"id"`
		Description   string   `json:"description"`
		JavaCommit    string   `json:"javaCommit"`
		JavaSource    string   `json:"javaSource"`
		JavaRuntimes  []string `json:"javaRuntimes"`
		JavaNames     []string `json:"javaNames"`
		JavaStaticIDs []string `json:"javaStaticIds"`
		JavaFlags     []string `json:"javaFlags"`
		Cases         []struct {
			Case              string `json:"case"`
			Ordinal           int    `json:"ordinal"`
			RuntimeID         string `json:"runtimeId"`
			ExecutionName     string `json:"executionName"`
			Observation       string `json:"observation"`
			IteratorSnapshots int    `json:"iteratorSnapshots"`
			EPL               string `json:"epl"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(data, &document); err != nil {
		t.Fatal(err)
	}
	if document.Version != compat.ScenarioVersion || document.ID != outputAfterEventsID ||
		document.Description != outputAfterEventsDescription ||
		document.JavaCommit != outputAfterEventsJavaCommit ||
		document.JavaSource != outputAfterEventsSource ||
		!reflect.DeepEqual(document.JavaRuntimes, outputAfterEventsJavaRuntimeIDs) ||
		!reflect.DeepEqual(document.JavaNames, outputAfterEventsJavaExecutions) ||
		!reflect.DeepEqual(document.JavaStaticIDs, outputAfterEventsJavaStaticIDs) ||
		len(document.JavaFlags) != 0 || len(document.Cases) != len(outputAfterEventsCases) {
		t.Fatalf("scenario metadata = %#v", document)
	}
	for index, entry := range document.Cases {
		if entry.Case != outputAfterEventsCases[index] ||
			entry.Ordinal != outputAfterEventsOrdinals[index] ||
			entry.RuntimeID != outputAfterEventsRuntimeID(outputAfterEventsCases[index]) ||
			entry.ExecutionName != outputAfterEventsJavaExecutions[index] ||
			entry.Observation != "listener" || entry.IteratorSnapshots != 0 ||
			entry.EPL != outputAfterEventsEPLs[index] {
			t.Fatalf("scenario case %d metadata = %#v", index, entry)
		}
	}
}

func assertOutputAfterEventsTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != outputAfterEventsID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 12 {
		t.Fatalf("trace records = %d, want 12", len(trace.Records))
	}
	listenerBatches := []struct {
		caseName    string
		sequence    uint64
		time        string
		values      []string
		wantFields  int
		recordIndex int
	}{
		{caseName: "after-3-events", sequence: 1, time: "1970-01-01T00:00:00Z", values: []string{"E4"}, wantFields: 1, recordIndex: 0},
		{caseName: "after-3-events", sequence: 2, time: "1970-01-01T00:00:00Z", values: []string{"E5"}, wantFields: 1, recordIndex: 1},
		{caseName: "after-3-events-when-then", sequence: 1, time: "1970-01-01T00:00:00Z", values: []string{"E4"}, wantFields: 2, recordIndex: 2},
		{caseName: "after-20-seconds", sequence: 1, time: "1970-01-01T00:00:20Z", values: []string{"E4"}, wantFields: 1, recordIndex: 5},
		{caseName: "after-20-seconds", sequence: 2, time: "1970-01-01T00:00:21Z", values: []string{"E5"}, wantFields: 1, recordIndex: 6},
		{caseName: "after-20-seconds-every-5", sequence: 1, time: "1970-01-01T00:00:25Z", values: []string{"E4", "E5"}, wantFields: 1, recordIndex: 7},
		{caseName: "after-20-seconds-every-5", sequence: 2, time: "1970-01-01T00:00:30Z", values: []string{"E6"}, wantFields: 1, recordIndex: 8},
		{caseName: "after-1-month", sequence: 1, time: "2002-03-01T09:00:00Z", values: []string{"E3"}, wantFields: 2, recordIndex: 9},
		{caseName: "after-20-seconds-snapshot-variable", sequence: 1, time: "1970-01-01T00:00:20Z", values: []string{"E1", "E2", "E3", "E4"}, wantFields: 1, recordIndex: 10},
		{caseName: "after-20-seconds-snapshot-variable", sequence: 2, time: "1970-01-01T00:00:21Z", values: []string{"E1", "E2", "E3", "E4", "E5"}, wantFields: 1, recordIndex: 11},
	}
	for _, batch := range listenerBatches {
		record := trace.Records[batch.recordIndex]
		if record.Case != batch.caseName ||
			record.Operation != "listener" || record.Statement != "s0" ||
			record.Sequence != batch.sequence || record.Time != batch.time ||
			len(record.New) != len(batch.values) || len(record.Old) != 0 {
			t.Fatalf("record %d metadata/shape = %#v", batch.recordIndex, record)
		}
		for rowIndex, row := range record.New {
			if row.Kind != "row" || len(row.Fields) != batch.wantFields ||
				row.Fields["theString"] != batch.values[rowIndex] {
				t.Fatalf("record %d row %d shape/identity = %#v", batch.recordIndex, rowIndex, row)
			}
		}
	}
	variableRecords := []struct {
		name  string
		value bool
	}{
		{name: "myvar1", value: true},
		{name: "myvar2", value: true},
	}
	for index, variable := range variableRecords {
		record := trace.Records[3+index]
		if record.Case != "after-3-events-when-then" ||
			record.Operation != "variable" || record.Name != variable.name ||
			record.Value != variable.value {
			t.Fatalf("record %d variable shape = %#v", 3+index, record)
		}
	}
}

