func TestRunInfraNWTableSubqCorrelCoerceDiffRejectsTraceMutations(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	tests := []struct {
		name   string
		mutate func(*compat.Trace)
	}{
		{
			name: "val-drift",
			mutate: func(trace *compat.Trace) {
				trace.Records[0].New[0].Fields["val"] = "W2"
			},
		},
		{
			name: "null-shape",
			mutate: func(trace *compat.Trace) {
				trace.Records[1].New[0].Fields["val"] = ""
			},
		},
		{
			name: "coercion-drift",
			mutate: func(trace *compat.Trace) {
				trace.Records[3].New[0].Fields["val"] = "W4"
			},
		},
		{
			name: "late-start-record-dropped",
			mutate: func(trace *compat.Trace) {
				trace.Records[6].New[0].Fields["val"] = nullStateCoerce()
			},
		},
		{
			name: "statement-swap",
			mutate: func(trace *compat.Trace) {
				trace.Records[2].Statement = "insert"
			},
		},
		{
			name: "sequence-drift",
			mutate: func(trace *compat.Trace) {
				trace.Records[6].Sequence = 1
			},
		},
		{
			name: "record-count-short",
			mutate: func(trace *compat.Trace) {
				trace.Records = trace.Records[:55]
			},
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			javaTracePath := writeJavaTraceFixtureFromEvidence(t,
				filepath.Join(root, infraNWTableSubqCorrelCoerceID+".evidence.json"), test.mutate)
			evidencePath := filepath.Join(t.TempDir(), infraNWTableSubqCorrelCoerceID+".evidence.json")
			var stdout, stderr bytes.Buffer
			code := Run([]string{
				"-mode", infraNWTableSubqCorrelCoerceID + "-diff",
				"-scenario", filepath.Join(root, infraNWTableSubqCorrelCoerceID+".json"),
				"-java-trace", javaTracePath,
				"-evidence", evidencePath,
			}, &stdout, &stderr)
			if code == 0 {
				t.Fatalf("mutation %q unexpectedly passed; stdout=%q stderr=%q", test.name, stdout.String(), stderr.String())
			}
			evidence, err := loadDifferentialEvidenceFile(evidencePath)
			if err != nil {
				t.Fatal(err)
			}
			if evidence.Status != "different" || len(evidence.Differences) == 0 {
				t.Fatalf("mutation %q evidence = %#v", test.name, evidence)
			}
		})
	}
}

func nullStateCoerce() map[string]any {
	return map[string]any{"state": "null"}
}

