func assertInfraNWTableSubqAtEventBeanTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != infraNWTableSubqAtEventBeanID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 6 {
		t.Fatalf("trace records = %d, want 6", len(trace.Records))
	}
	nullState := map[string]any{"state": "null"}
	offset := 0
	for _, caseName := range infraNWTableSubqAtEventBeanCases {
		detailRows := [][]map[string]any{
			nil,
			{{"c0": "E1", "c1": json.Number("1")}},
			{{"c0": "E1", "c1": json.Number("1")}, {"c0": "E2", "c1": json.Number("2")}},
		}
		for index, wantDetail := range detailRows {
			record := trace.Records[offset]
			offset++
			if record.Case != caseName || record.Operation != "listener" || record.Statement != "s0" ||
				record.Sequence != uint64(index+1) || record.Time != "1970-01-01T00:00:00Z" {
				t.Fatalf("%s record %d metadata = %#v", caseName, index, record)
			}
			if len(record.New) != 1 || len(record.Old) != 0 {
				t.Fatalf("%s record %d shape = %#v", caseName, index, record)
			}
			fields := record.New[0].Fields
			if !reflect.DeepEqual(fields["p00"], nullState) {
				t.Fatalf("%s record %d p00 = %#v, want null state", caseName, index, fields["p00"])
			}
			if wantDetail == nil {
				if !reflect.DeepEqual(fields["detail"], nullState) {
					t.Fatalf("%s record %d detail = %#v, want null state", caseName, index, fields["detail"])
				}
				continue
			}
			rows, ok := fields["detail"].([]any)
			if !ok || len(rows) != len(wantDetail) {
				t.Fatalf("%s record %d detail = %#v", caseName, index, fields["detail"])
			}
			for rowIndex, element := range rows {
				rowFields := element.(map[string]any)["fields"].(map[string]any)
				want := wantDetail[rowIndex]
				if rowFields["c0"] != want["c0"] || !valueMatches(rowFields["c1"], mustInt64(t, want["c1"])) {
					t.Fatalf("%s record %d detail row %d = %#v", caseName, index, rowIndex, rowFields)
				}
			}
		}
	}
	if offset != len(trace.Records) {
		t.Fatalf("trace has %d trailing records", len(trace.Records)-offset)
	}
}
